"""
MA(45) long-only — manual SMA(45) from bar.close[offset].
Rules: close > SMA(45) → add longs (cap 5); close < SMA(45) → flat. No Backtrader.

Symbols from engine only: on_bar / on_tick receive symbol; clock = qc_ohlcv in qc_ohlcv_by_symbol.

Use warmup_bars in the modal so bar.close[44] exists. Optional: fundamentals for B2 prior-quarter.

Multi-symbol: pass symbol= on chart_indicators.add.
"""

from __future__ import annotations

import math
from datetime import datetime, timezone
from typing import Any

import pandas as pd

import ide.backtest.runtime as rt
from ide.fundamentals_module import BacktestFundamentals
from ide.inputs_module import params

MAX_OPEN_LONGS = params.MAX_OPEN_LONGS
PERIOD = params.PERIOD

_sma_by_symbol: dict[str, list[float]] = {}
_bar_times_by_symbol: dict[str, list[Any]] = {}


def _clock_symbol() -> str:
    qc = rt.qc_ohlcv
    by_sym = rt.qc_ohlcv_by_symbol
    if qc is not None and by_sym:
        for sym, q in by_sym.items():
            if q is qc:
                return sym
        if len(by_sym) == 1:
            return next(iter(by_sym.keys()))
    return "UNKNOWN"


def _active_symbol(symbol: str | None) -> str:
    s = (symbol or "").strip().upper()
    if s:
        return s
    c = _clock_symbol()
    return c if c != "UNKNOWN" else "DEFAULT"


def _series_key(symbol: str | None) -> str:
    s = _active_symbol(symbol)
    return s if s not in ("UNKNOWN", "DEFAULT") else _clock_symbol()


def _close0(bar: Any) -> float | None:
    v = bar.close[0]
    if v is None:
        return None
    return float(v)


def _sma_45(bar: Any) -> float | None:
    acc: list[float] = []
    for i in range(PERIOD):
        v = bar.close[i]
        if v is None:
            return None
        acc.append(float(v))
    return sum(acc) / PERIOD


def _bar_time_raw(bar: Any) -> Any:
    t0 = bar.t[0]
    return t0 if t0 is not None else bar.get("t")


def _dt_from_bar(bar: Any) -> datetime | None:
    raw = _bar_time_raw(bar)
    if raw is None:
        return None
    if isinstance(raw, datetime):
        dt = raw
        return (
            dt.replace(tzinfo=timezone.utc)
            if dt.tzinfo is None
            else dt.astimezone(timezone.utc)
        )
    ts = pd.Timestamp(raw)
    if pd.isna(ts):
        return None
    dt = ts.to_pydatetime()
    return (
        dt.replace(tzinfo=timezone.utc)
        if dt.tzinfo is None
        else dt.astimezone(timezone.utc)
    )


def on_init() -> None:
    if rt.account is None or rt.qc_ohlcv is None:
        print("ma45: runtime not ready")
        return
    n = len(list(reversed(rt.qc_ohlcv.bars)))
    clk = _clock_symbol()
    extra = ""
    if rt.qc_ohlcv_by_symbol:
        extra = f"; symbols={list(rt.qc_ohlcv_by_symbol.keys())}; clock={clk}"


def on_tick(
    bar_index: int,
    tick_in_bar: int,
    price: float,
    bar: Any,
    fundamentals: BacktestFundamentals | None = None,
    *,
    symbol: str | None = None,
) -> None:
    acc = rt.account
    if fundamentals:
        snap_msft = fundamentals.current(bar.t[0], symbol="MSFT")
        # print(f"fundamentals data: {snap_msft}")
    npos = len(getattr(acc, "_positions", {})) if acc is not None else 0
    print(bar_index, tick_in_bar, price, bar, symbol, npos)
    _ = (bar_index, tick_in_bar, price, bar, fundamentals, symbol)


def on_bar(
    bar_index: int,
    bar: Any,
    fundamentals: BacktestFundamentals | None = None,
    *,
    symbol: str | None = None,
) -> None:
    acc = rt.account
    npos = len(getattr(acc, "_positions", {})) if acc is not None else 0
    print("on bar running", symbol, npos)
    global _sma_by_symbol, _bar_times_by_symbol

    sym = _active_symbol(symbol)

    if sym not in _sma_by_symbol:
        _sma_by_symbol[sym] = []
        _bar_times_by_symbol[sym] = []

    c = _close0(bar)
    ma = _sma_45(bar)

    if ma is not None:
        _sma_by_symbol[sym].append(ma)
        _bar_times_by_symbol[sym].append(_bar_time_raw(bar))

    if fundamentals is not None:
        bt = _dt_from_bar(bar)
        if bt is not None:
            pq = fundamentals.get_data_with_offset(
                bt,
                1,
                symbol=sym,
                print_on_shortfall=False,
            )
            ta_p = ((pq or {}).get("balanceSheet") or {}).get("quarterly")
            ta_p = ta_p.get("totalAssets") if isinstance(ta_p, dict) else None

    if acc is None or ma is None or c is None:
        return

    if c < ma:
        acc.close_all_longs(c, symbol=sym)
        print(f"Trades closed: {sym} {bar.t[0]} price: {c} {bar.close[0]}, ma: {ma}")
        return

    n_open = len(getattr(acc, "_positions", {}))

    if n_open < MAX_OPEN_LONGS and c > ma:
        cash = float(acc.cash)
        if cash <= 0 or c <= 0:
            return
        slots = max(1, MAX_OPEN_LONGS - n_open)
        alloc = min(cash * 0.1, cash / slots)
        qty = alloc / c
        if qty * c <= cash + 1e-6:
            acc.open_trade(sym, "long", qty, c)


def on_finish() -> None:
    from ide.backtest.indicator_series_module import coerce_chart_time

    ci = rt.chart_indicators
    if ci is None:
        return

    for sym in sorted(_bar_times_by_symbol.keys()):
        times = _bar_times_by_symbol.get(sym, [])
        vals = _sma_by_symbol.get(sym, [])
        if not times or not vals:
            continue

        points: list[dict[str, Any]] = []
        for t, v in zip(times, vals):
            if isinstance(v, float) and (math.isnan(v) or math.isinf(v)):
                continue
            ct = coerce_chart_time(t)
            if ct is None:
                continue
            points.append({"time": ct, "value": float(v)})

        if not points:
            continue

        ci.add(
            points,
            pane="main",
            render="line",
            line_style="solid",
            id=f"sma_45_{sym}",
            name=f"SMA(45) {sym}",
            color="#ff9800",
            symbol=sym,
        )

        print("Test completed with parameters: ", PERIOD, MAX_OPEN_LONGS)


def on_timer(bar_index, tick_in_bar, price, bar, fundamentals=None, symbol=None):
    acc = rt.account
    if fundamentals:
        snap_msft = fundamentals.current(bar.t[0], symbol="MSFT")
        print(f"fundamentals data: {snap_msft}")
    npos = len(getattr(acc, "_positions", {})) if acc is not None else 0
    print("Timer bar: ", bar_index, tick_in_bar, price, bar, fundamentals, symbol, npos)
